package projection

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// vectorFile mirrors go/testdata/vectors/projection-scenarios.json, generated by
// scripts/go-rewrite/gen-projection-vectors.mts from the REAL TypeScript
// ProductProjection. The test must reproduce every raw per-event delta, the
// coalesced stream, and the final snapshot byte-for-byte (including key order).
type vectorFile struct {
	GeneratedBy string `json:"generatedBy"`
	Session     string `json:"session"`
	LogEpoch    string `json:"logEpoch"`
	Scenarios   []struct {
		ID                 string            `json:"id"`
		Description        string            `json:"description"`
		SourceTrace        string            `json:"sourceTrace"`
		Prelude            []eventCase       `json:"prelude"`
		Events             []eventCase       `json:"events"`
		Coalesced          []json.RawMessage `json:"coalesced"`
		SnapshotBeforeLive json.RawMessage   `json:"snapshotBeforeLive"`
		FinalSnapshot      json.RawMessage   `json:"finalSnapshot"`
	} `json:"scenarios"`
}

type eventCase struct {
	Input  json.RawMessage   `json:"input"`
	Deltas []json.RawMessage `json:"deltas"`
}

func loadVectors(t *testing.T) vectorFile {
	t.Helper()
	path := filepath.Join("..", "..", "testdata", "vectors", "projection-scenarios.json")
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read vectors: %v", err)
	}
	var vf vectorFile
	if err := json.Unmarshal(data, &vf); err != nil {
		t.Fatalf("parse vectors: %v", err)
	}
	if len(vf.Scenarios) == 0 {
		t.Fatal("no scenarios in vector file")
	}
	return vf
}

// applyEventCase runs one event through the projection and returns its deltas as
// canonical JSON (one entry per delta, byte-exact via the ordered encoder).
func applyEventCase(t *testing.T, p *Projection, raw json.RawMessage) []json.RawMessage {
	t.Helper()
	event, err := ParseEvent(raw)
	if err != nil {
		t.Fatalf("parse event: %v", err)
	}
	deltas, err := p.Apply(event)
	if err != nil {
		t.Fatalf("apply event: %v", err)
	}
	out := make([]json.RawMessage, 0, len(deltas))
	for _, d := range deltas {
		data, err := d.MarshalJSON()
		if err != nil {
			t.Fatalf("marshal delta: %v", err)
		}
		out = append(out, data)
	}
	return out
}

func TestScenariosReproduceTypeScriptRawDeltas(t *testing.T) {
	vf := loadVectors(t)
	for _, scenario := range vf.Scenarios {
		scenario := scenario
		t.Run(scenario.ID, func(t *testing.T) {
			p := New(vf.Session, vf.LogEpoch)
			for i, ec := range scenario.Prelude {
				got := applyEventCase(t, p, ec.Input)
				assertJSONList(t, "prelude", scenario.ID, i, got, ec.Deltas)
			}
			for i, ec := range scenario.Events {
				got := applyEventCase(t, p, ec.Input)
				assertJSONList(t, "event", scenario.ID, i, got, ec.Deltas)
			}
		})
	}
}

func TestScenariosReproduceCoalescedStream(t *testing.T) {
	vf := loadVectors(t)
	for _, scenario := range vf.Scenarios {
		scenario := scenario
		t.Run(scenario.ID, func(t *testing.T) {
			p := New(vf.Session, vf.LogEpoch)
			var all []Delta
			for _, ec := range scenario.Prelude {
				event, err := ParseEvent(ec.Input)
				if err != nil {
					t.Fatalf("parse prelude event: %v", err)
				}
				if _, err := p.Apply(event); err != nil {
					t.Fatalf("apply prelude event: %v", err)
				}
			}
			for _, ec := range scenario.Events {
				event, err := ParseEvent(ec.Input)
				if err != nil {
					t.Fatalf("parse event: %v", err)
				}
				deltas, err := p.Apply(event)
				if err != nil {
					t.Fatalf("apply event: %v", err)
				}
				all = append(all, deltas...)
			}
			coalesced := coalesceConversationDeltas(all)
			got := make([]json.RawMessage, 0, len(coalesced))
			for _, d := range coalesced {
				data, err := d.MarshalJSON()
				if err != nil {
					t.Fatalf("marshal delta: %v", err)
				}
				got = append(got, data)
			}
			assertJSONList(t, "coalesced", scenario.ID, 0, got, scenario.Coalesced)
		})
	}
}

func TestScenariosReproduceFinalSnapshot(t *testing.T) {
	vf := loadVectors(t)
	for _, scenario := range vf.Scenarios {
		scenario := scenario
		t.Run(scenario.ID, func(t *testing.T) {
			p := New(vf.Session, vf.LogEpoch)
			for _, ec := range append(append([]eventCase{}, scenario.Prelude...), scenario.Events...) {
				event, err := ParseEvent(ec.Input)
				if err != nil {
					t.Fatalf("parse event: %v", err)
				}
				if _, err := p.Apply(event); err != nil {
					t.Fatalf("apply event: %v", err)
				}
			}
			got, err := p.Snapshot()
			if err != nil {
				t.Fatalf("snapshot: %v", err)
			}
			assertJSONEqual(t, "final snapshot "+scenario.ID, got, scenario.FinalSnapshot)
		})
	}
}

func assertJSONList(t *testing.T, kind, id string, index int, got, want []json.RawMessage) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s %s[%d]: delta count %d != want %d\ngot=%s\nwant=%s",
			id, kind, index, len(got), len(want), joinRaw(got), joinRaw(want))
	}
	for i := range got {
		assertJSONEqual(t, id+" "+kind+"#"+itoa(int64(index))+"."+itoa(int64(i)), got[i], want[i])
	}
}

// assertJSONEqual compares two JSON values ignoring insignificant whitespace but
// preserving key order (json.Compact only strips whitespace).
func assertJSONEqual(t *testing.T, label string, got, want json.RawMessage) {
	t.Helper()
	// The vector file is pretty-printed, so compare after stripping insignificant
	// whitespace. json.Compact preserves key order, so the ordering guarantee
	// (the encoder must mirror the TS object-literal order) is still enforced.
	compactGot := compact(t, got)
	compactWant := compact(t, want)
	if compactGot == compactWant {
		return
	}
	t.Fatalf("%s: JSON differs\n got=%s\nwant=%s", label, compactGot, compactWant)
}

func compact(t *testing.T, raw []byte) string {
	t.Helper()
	var buf bytes.Buffer
	if err := json.Compact(&buf, raw); err != nil {
		t.Fatalf("compact JSON: %v", err)
	}
	return buf.String()
}

func joinRaw(items []json.RawMessage) string {
	out := "["
	for i, item := range items {
		if i > 0 {
			out += ","
		}
		out += string(item)
	}
	return out + "]"
}
